implementation:
(*
======================================================================================================================
 SAFETY Alias Outputs
======================================================================================================================
*)
GVL_Safety.bSafetyRunRequest 					:= GVL_IO.stOutputs.bSafetyRunRequest;
GVL_Safety.bSafetyResetRequest 					:= GVL_IO.stOutputs.bSafetyResetRequest;
GVL_Safety.bSafetyErrorAcknowledgementRequest 	:= GVL_IO.stOutputs.bSafetyErrorAcknowledgementRequest;
GVL_Safety.bAirSupplyEnableRequest 				:= GVL_IO.stOutputs.bAirSupplyEnable;
GVL_Safety.bMainDoorLockRequest 				:= GVL_IO.stOutputs.bMainDoorLockRequest;

(*
======================================================================================================================
 Terminal 9 | EL2809
======================================================================================================================
*)
GVL_EtherCAT.stTerm9_EL2809.iEL2809_Ch1 := GVL_IO.stOutputs.bLedStart;
GVL_EtherCAT.stTerm9_EL2809.iEL2809_Ch2 := GVL_IO.stOutputs.bLedReset;

// Validated physical status-light mapping:
// Ch3 = RED status indicator (driven from machine FAIL)
// Ch4 = GREEN status indicator (driven from machine PASS)
GVL_EtherCAT.stTerm9_EL2809.iEL2809_Ch3 := GVL_IO.stOutputs.bStatusIndicatorRed;
GVL_EtherCAT.stTerm9_EL2809.iEL2809_Ch4 := GVL_IO.stOutputs.bStatusIndicatorGreen;

// Ch5 = internal cabinet/machine light
// Ch6 = operator/nest light
GVL_EtherCAT.stTerm9_EL2809.iEL2809_Ch5 := GVL_IO.stOutputs.bInternalLight;
GVL_EtherCAT.stTerm9_EL2809.iEL2809_Ch6 := GVL_IO.stOutputs.bNestLight;
// Monostable Heat Stake valve: TRUE = UP, FALSE = DOWN.
GVL_EtherCAT.stTerm9_EL2809.iEL2809_Ch7 := GVL_IO.stOutputs.bHeatStakeHeadUp;

(*
======================================================================================================================
 Terminal 13 | EL2502 | Heat Stake PWM Outputs
======================================================================================================================
*)
// IMPORTANT - VALIDATED PHYSICAL MAPPING.
// The heater channels are intentionally crossed relative to logical Heater 1 / Heater 2.
// Do NOT "correct" this unless the physical wiring is changed.
//
// EL2502 Ch1 physically drives logical Heater 2.
// EL2502 Ch2 physically drives logical Heater 1.
GVL_EtherCAT.stTerm13_EL2502.iEL2502_Ch1 := GVL_IO.stOutputs.uiHeatStakePwm2Raw;
GVL_EtherCAT.stTerm13_EL2502.iEL2502_Ch2 := GVL_IO.stOutputs.uiHeatStakePwm1Raw;

(*
======================================================================================================================
 BOX 1 | Festo VABX EtherCAT manifold - Module 2
======================================================================================================================
*)

// Module2.Coil0 = Index Table A - rotate index
// Module2.Coil1 = Index Table B - return index cylinder to home
// Module2.Coil2 = Support UP   - Dispense Station
// Module2.Coil3 = Support DOWN - Dispense Station
// Module2.Coil4 = Support UP   - Heat Stake Station
// Module2.Coil5 = Support DOWN - Heat Stake Station
// Module2.Coil6 = Support UP   - Vision Station
// Module2.Coil7 = Support DOWN - Vision Station
//
// Application naming:
// UP   = Extend
// DOWN = Retract
GVL_EtherCAT.stFestoModule2_VABX.bCoil0 := GVL_IO.stOutputs.bIndexRotatePortA;
GVL_EtherCAT.stFestoModule2_VABX.bCoil1 := GVL_IO.stOutputs.bIndexStopPortB;

GVL_EtherCAT.stFestoModule2_VABX.bCoil2 := GVL_IO.stOutputs.bStation1SupportExtend;
GVL_EtherCAT.stFestoModule2_VABX.bCoil3 := GVL_IO.stOutputs.bStation1SupportRetract;

GVL_EtherCAT.stFestoModule2_VABX.bCoil4 := GVL_IO.stOutputs.bStation2SupportExtend;
GVL_EtherCAT.stFestoModule2_VABX.bCoil5 := GVL_IO.stOutputs.bStation2SupportRetract;

GVL_EtherCAT.stFestoModule2_VABX.bCoil6 := FALSE; // Removed Vision hardware: never energise.
GVL_EtherCAT.stFestoModule2_VABX.bCoil7 := FALSE; // Removed Vision hardware: never energise.

(*
======================================================================================================================
 BOX 1 | Festo VABX EtherCAT manifold - Module 3 | Vision Flipping
======================================================================================================================
*)
// Mapping confirmed from the commissioned GVL_EtherCAT / manifold layout.
// Coil0 = Horizontal slide BACK
// Coil1 = Horizontal slide FRONT
// Coil2 = Vertical cylinder UP
// Coil3 = Vertical cylinder DOWN
// Coil4 = Vertical cylinder limit OFF
// Coil5 = Vertical cylinder limit ON
// Coil6 = Grip CLOSE
// Coil7 = Grip OPEN
GVL_EtherCAT.stFestoModule3_VABX.bCoil0 := GVL_IO.stOutputs.bVisionHorizontalBack;
GVL_EtherCAT.stFestoModule3_VABX.bCoil1 := GVL_IO.stOutputs.bVisionHorizontalFront;
GVL_EtherCAT.stFestoModule3_VABX.bCoil2 := GVL_IO.stOutputs.bVisionVerticalUp;
GVL_EtherCAT.stFestoModule3_VABX.bCoil3 := GVL_IO.stOutputs.bVisionVerticalDown;
GVL_EtherCAT.stFestoModule3_VABX.bCoil4 := FALSE; // Removed Vision hardware: never energise.
GVL_EtherCAT.stFestoModule3_VABX.bCoil5 := FALSE; // Removed Vision hardware: never energise.
GVL_EtherCAT.stFestoModule3_VABX.bCoil6 := GVL_IO.stOutputs.bVisionGripOpen;
GVL_EtherCAT.stFestoModule3_VABX.bCoil7 := GVL_IO.stOutputs.bVisionGripClose;
(*
======================================================================================================================
 BOX 1 | Festo VABX EtherCAT manifold - Module 4 | Heat Stake Head
======================================================================================================================
*)
// Mapping confirmed from the commissioned GVL_EtherCAT / manifold layout.
// Coil0 = Vision gripper rotation 0Â° / PICK
// Coil1 = Vision gripper rotation 180Â° / PLACE
// Coil2 = Patch dispenser AIR
// Coil3 = Heat Stake head UNLOCK
// Coil4 = retired head DOWN output (always OFF)
// Coil5 = continuous pilot supply for the external head valve
// Coil6 = Patch vertical support DOWN
// Coil7 = Patch vertical support UP

GVL_EtherCAT.stFestoModule4_VABX.bCoil0 := GVL_IO.stOutputs.bVisionRotate0;
GVL_EtherCAT.stFestoModule4_VABX.bCoil1 := GVL_IO.stOutputs.bVisionRotate180;
GVL_EtherCAT.stFestoModule4_VABX.bCoil2 := GVL_IO.stOutputs.bPatchDispenserAir;
GVL_EtherCAT.stFestoModule4_VABX.bCoil3 := GVL_IO.stOutputs.bHeatStakeHeadUnlock;
GVL_EtherCAT.stFestoModule4_VABX.bCoil4 := FALSE; // Retired direction output.
GVL_EtherCAT.stFestoModule4_VABX.bCoil5 := TRUE; // Continuous pilot supply; reservoir supports retraction.
GVL_EtherCAT.stFestoModule4_VABX.bCoil6 := GVL_IO.stOutputs.bPatchVerticalDown;
GVL_EtherCAT.stFestoModule4_VABX.bCoil7 := GVL_IO.stOutputs.bPatchVerticalUp;

(*
======================================================================================================================
 Terminal 21 | EL4028 | VEAB Heat Stake Down Pressure
======================================================================================================================
*)
GVL_EtherCAT.stTerm21_EL4028.iEL4028_Ch1 := GVL_IO.stOutputs.iHeatStakePressureRaw;
